import{_ as u,a0 as p,w as d,s as r,ao as l,I as o,x as n,a1 as e,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"神器：在一個 U 盤上放入多個 Linux 發行版 | LCTT x X-CMD","titleTemplate":false,"description":"神器：在一個 U 盤上放入多個 Linux 發行版 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"神器：在一個 U 盤上放入多個 Linux 發行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"神器：在一個 U 盤上放入多個 Linux 發行版 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210504 Keep multiple Linux distros on a USB with this open source tool","title":"神器：在一個 U 盤上放入多個 Linux 發行版","tag":"202105","desc":""},"relativePath":"202105/20210504 Keep multiple Linux distros on a USB with this open source tool.md","filePath":"[post].md"}'),a={name:"202105/20210504 Keep multiple Linux distros on a USB with this open source tool.md"};function x(m,t,f,y,g,L){const i=p("Link");return d(),r("div",null,[t[39]||(t[39]=l('<h1 id="神器-在一個-u-盤上放入多個-linux-發行版" tabindex="-1">神器：在一個 U 盤上放入多個 Linux 發行版 <a class="header-anchor" href="#神器-在一個-u-盤上放入多個-linux-發行版" aria-label="Permalink to “神器：在一個 U 盤上放入多個 Linux 發行版”">​</a></h1><blockquote><p>用 Ventoy 創建多啓動 U 盤，你將永遠不會缺少自己喜歡的 Linux 發行版。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202105/05/131432p5q7hh5cm7a8ffsd.jpg" alt=""></p><p>給朋友和鄰居一個可啓動 U 盤，裏面包含你最喜歡的 Linux 發行版，是向 Linux 新手介紹我們都喜歡的 Linux 體驗的好方法。仍然有許多人從未聽説過 Linux，把你喜歡的發行版放在一個可啓動的 U 盤上是讓他們進入 Linux 世界的好辦法。</p><p>幾年前，我在給一羣中學生教授計算機入門課。我們使用舊筆記本電腦，我向學生們介紹了 Fedora、Ubuntu 和 Pop!_OS。下課後，我給每個學生一份他們喜歡的發行版的副本，讓他們帶回家安裝在自己選擇的電腦上。他們渴望在家裏嘗試他們的新技能。</p><h3 id="把多個發行版放在一個驅動器上" tabindex="-1">把多個發行版放在一個驅動器上 <a class="header-anchor" href="#把多個發行版放在一個驅動器上" aria-label="Permalink to “把多個發行版放在一個驅動器上”">​</a></h3>',6)),o("p",null,[t[1]||(t[1]=n("最近，一個朋友向我介紹了 Ventoy，它（根據其 ",-1)),e(i,{href:"https://github.com/ventoy/Ventoy"},{default:s(()=>[...t[0]||(t[0]=[n("GitHub 倉庫",-1)])]),_:1}),t[2]||(t[2]=n("）是 “一個開源工具，可以為 ISO/WIM/IMG/VHD(x)/EFI 文件創建可啓動的 USB 驅動器”。與其為每個我想分享的 Linux 發行版創建單獨的驅動器，我可以在一個 U 盤上放入我喜歡的 ",-1)),t[3]||(t[3]=o("em",null,"所有",-1)),t[4]||(t[4]=n(" Linux 發行版！",-1))]),t[40]||(t[40]=o("p",null,[o("img",{src:"https://opensource.com/sites/default/files/uploads/ventoy1.png",alt:"USB 空間",title:"USB space"})],-1)),t[41]||(t[41]=o("p",null,"正如你所能想到的那樣，U 盤的大小決定了你能在上面容納多少個發行版。在一個 16GB 的 U 盤上，我放置了 Elementary 5.1、Linux Mint Cinnamon 5.1 和 Linux Mint XFCE 5.1......但仍然有 9.9GB 的空間。",-1)),t[42]||(t[42]=o("h3",{id:"獲取-ventoy",tabindex:"-1"},[n("獲取 Ventoy "),o("a",{class:"header-anchor",href:"#獲取-ventoy","aria-label":"Permalink to “獲取 Ventoy”"},"​")],-1)),o("p",null,[t[6]||(t[6]=n("Ventoy 是開源的，採用 ",-1)),e(i,{href:"https://www.ventoy.net/en/doc_license.html"},{default:s(()=>[...t[5]||(t[5]=[n("GPLv3",-1)])]),_:1}),t[7]||(t[7]=n(" 許可證，可用於 Windows 和 Linux。有很好的文檔介紹瞭如何在 Windows 上下載和安裝 Ventoy。Linux 的安裝是通過命令列進行的，所以如果你不熟悉這個過程，可能會有點混亂。然而，其實很容易。",-1))]),o("p",null,[t[9]||(t[9]=n("首先，",-1)),e(i,{href:"https://github.com/ventoy/Ventoy/releases"},{default:s(()=>[...t[8]||(t[8]=[n("下載 Ventoy",-1)])]),_:1}),t[10]||(t[10]=n("。我把存檔文件下載到我的桌面上。",-1))]),t[43]||(t[43]=l('<p>接下來，使用 <code>tar</code> 命令解壓 <code>ventoy-x.y.z-linux.tar.gz</code> 檔案（但要用你下載的版本號替換 <code>x.y.z</code>）（為了保持簡單，我在命令中使用 <code>*</code> 字符作為任意通配符）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -xvf ventoy*z</span></span></code></pre></div><p>這個命令將所有必要的文件提取到我桌面上一個名為 <code>ventoy-x.y.z</code> 的文件夾中。</p><p>你也可以使用你的 Linux 發行版的存檔管理器來完成同樣的任務。下載和提取完成後，你就可以把 Ventoy 安裝到你的 U 盤上了。</p><h3 id="在-u-盤上安裝-ventoy-和-linux" tabindex="-1">在 U 盤上安裝 Ventoy 和 Linux <a class="header-anchor" href="#在-u-盤上安裝-ventoy-和-linux" aria-label="Permalink to “在 U 盤上安裝 Ventoy 和 Linux”">​</a></h3>',5)),o("p",null,[t[12]||(t[12]=n("把你的 U 盤插入你的電腦。改變目錄進入 Ventoy 的文件夾，並尋找一個名為 ",-1)),t[13]||(t[13]=o("code",null,"Ventoy2Disk.sh",-1)),t[14]||(t[14]=n(" 的 shell 腳本。你需要確定你的 U 盤的正確掛載點，以便這個腳本能夠正常工作。你可以通過在命令列上發出 ",-1)),t[15]||(t[15]=o("code",null,"mount",-1)),t[16]||(t[16]=n(" 命令或者使用 ",-1)),e(i,{href:"https://wiki.gnome.org/Apps/Disks"},{default:s(()=>[...t[11]||(t[11]=[n("GNOME 磁盤",-1)])]),_:1}),t[17]||(t[17]=n(" 來找到它，後者提供了一個圖形界面。後者顯示我的 U 盤被掛載在 ",-1)),t[18]||(t[18]=o("code",null,"/dev/sda",-1)),t[19]||(t[19]=n("。在你的電腦上，這個位置可能是 ",-1)),t[20]||(t[20]=o("code",null,"/dev/sdb",-1)),t[21]||(t[21]=n(" 或 ",-1)),t[22]||(t[22]=o("code",null,"/dev/sdc",-1)),t[23]||(t[23]=n(" 或類似的位置。",-1))]),t[44]||(t[44]=l('<p><img src="https://opensource.com/sites/default/files/uploads/usb-mountpoint.png" alt="GNOME 磁盤中的 USB 掛載點" title="USB mount point in GNOME Disks"></p><p>下一步是執行 Ventoy shell 腳本。因為它被設計成不加選擇地複製數據到一個驅動器上，我使用了一個假的位置（<code>/dev/sdX</code>）來防止你複製/粘貼錯誤，所以用你想覆蓋的實際驅動器的字母替換後面的 <code>X</code>。</p><p><strong>讓我重申</strong>：這個 shell 腳本的目的是把數據複製到一個驅動器上， <em>破壞該驅動器上的所有數據。</em> 如果該驅動器上有你關心的數據，在嘗試這個方法之前，先把它備份! 如果你不確定你的驅動器的位置，在你繼續進行之前，請驗證它，直到你完全確定為止。</p><p>一旦你確定了你的驅動器的位置，就運行這個腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sh Ventoy2Disk.sh -i /dev/sdX</span></span></code></pre></div><p>這樣就可以格式化它並將 Ventoy 安裝到你的 U 盤上。現在你可以複製和粘貼所有適合放在 U 盤上的 Linux 發行版文件。如果你在電腦上用新創建的 U 盤引導，你會看到一個菜單，上面有你複製到 U 盤上的發行版。</p><p><img src="https://opensource.com/sites/default/files/uploads/ventoy_distros.jpg" alt="Ventoy 中的 Linux 發行版" title="Linux distros in Ventoy"></p><h3 id="構建一個便攜式的動力源" tabindex="-1">構建一個便攜式的動力源 <a class="header-anchor" href="#構建一個便攜式的動力源" aria-label="Permalink to “構建一個便攜式的動力源”">​</a></h3><p>Ventoy 是你在鑰匙串上攜帶多啓動 U 盤的關鍵（鑰匙），這樣你就永遠不會缺少你所依賴的發行版。你可以擁有一個全功能的桌面、一個輕量級的發行版、一個純控制台的維護工具，以及其他你想要的東西。</p><p>我從來沒有在沒有 Linux 發行版的情況下離開家，你也不應該。拿上 Ventoy、一個 U 盤，和一串 ISO。你不會後悔的。</p><hr>',11)),o("p",null,[t[25]||(t[25]=n("via: ",-1)),e(i,{href:"https://opensource.com/article/21/5/linux-ventoy"},{default:s(()=>[...t[24]||(t[24]=[n("https://opensource.com/article/21/5/linux-ventoy",-1)])]),_:1})]),o("p",null,[t[30]||(t[30]=n("作者：",-1)),e(i,{href:"https://opensource.com/users/don-watkins"},{default:s(()=>[...t[26]||(t[26]=[n("Don Watkins",-1)])]),_:1}),t[31]||(t[31]=n(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[27]||(t[27]=[n("lujun9972",-1)])]),_:1}),t[32]||(t[32]=n(" 譯者：",-1)),e(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[28]||(t[28]=[n("wxy",-1)])]),_:1}),t[33]||(t[33]=n(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[29]||(t[29]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[36]||(t[36]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[34]||(t[34]=[n("LCTT",-1)])]),_:1}),t[37]||(t[37]=n(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:s(()=>[...t[35]||(t[35]=[n("Linux中國",-1)])]),_:1}),t[38]||(t[38]=n(" 榮譽推出",-1))])])}const U=u(a,[["render",x]]);export{T as __pageData,U as default};
